import { ProfilePatch } from './types';

const PATCH_FIELDS: ReadonlySet<string> = new Set(['displayName', 'tags']);
const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

// Accepts only object literals and null-prototype objects. Arrays, class
// instances and objects with any other prototype are rejected.
function isPlainObject(input: unknown): input is object {
  if (typeof input !== 'object' || input === null) return false;
  const proto: unknown = Object.getPrototypeOf(input);
  return proto === Object.prototype || proto === null;
}

// Returns the own data property's value, or undefined when the key is absent.
// Accessor properties are rejected so that no getter runs during parsing.
function readOwnData(target: object, key: PropertyKey): { value: unknown } | undefined {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (descriptor === undefined) return undefined;
  if (!('value' in descriptor)) invalid();
  return { value: descriptor.value };
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value) || value.length > MAX_TAGS) invalid();
  const seen = new Set<string>();
  const tags: string[] = [];
  for (let index = 0; index < value.length; index++) {
    // Holes and accessor elements have no plain data value and are invalid.
    const element = readOwnData(value, index);
    if (element === undefined || typeof element.value !== 'string') invalid();
    const tag = element.value.trim();
    if (tag.length < 1 || tag.length > MAX_TAG_LENGTH || seen.has(tag)) invalid();
    seen.add(tag);
    tags.push(tag);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (typeof key !== 'string' || !PATCH_FIELDS.has(key)) invalid();
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  const rawDisplayName = readOwnData(input, 'displayName');
  if (rawDisplayName !== undefined) {
    displayName = { kind: 'set', value: parseDisplayName(rawDisplayName.value) };
  }
  const rawTags = readOwnData(input, 'tags');
  if (rawTags !== undefined) {
    tags = { kind: 'set', value: parseTags(rawTags.value) };
  }
  return { displayName, tags };
